import {createVP,elapsedMinutes,transitionVP,recordVP,restoreVP} from './vp.js';

const KEY='ccpc-rank-vp-v1';
const clock=n=>{const seconds=Math.max(0,Math.floor(n*60));return `${String(Math.floor(seconds/3600)).padStart(2,'0')}:${String(Math.floor(seconds/60)%60).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;};
export function createVPUI(host){
 const {$,esc,icon,toast}=host;
 let sessions=[],viewId=null;
 function load(){try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');sessions=(saved?.sessions||[]).map(s=>restoreVP(s,host.contests().find(c=>c.id===s.contestId))).filter(Boolean);viewId=saved?.viewId||null;}catch{sessions=[];viewId=null;}}
 function save(){try{localStorage.setItem(KEY,JSON.stringify({sessions,viewId}));}catch{toast('VP 进度无法写入浏览器，请使用「导出 VP 记录」备份');}}
 function selected(c=host.active()){return sessions.find(s=>s.contestId===c.id&&s.status!=='finished')||sessions.find(s=>s.id===viewId&&s.contestId===c.id)||null;}
 function activeSession(){return sessions.find(s=>s.status!=='finished');}
 function locked(c=host.active()){const s=selected(c);return !!s&&s.status!=='finished';}
 function update(s){sessions=sessions.map(x=>x.id===s.id?s:x);save();host.change();}
 function rules(c,fallback){return selected(c)?.rules||fallback;}
 function medals(c,fallback){return selected(c)?.medals||fallback;}
 function medalPolicy(c,fallback){const s=selected(c);return s?s.medalPolicy||null:fallback;}
 function finishIfExpired(){const s=activeSession(),c=s&&host.contests().find(c=>c.id===s.contestId);if(c&&elapsedMinutes(s,c.duration)>=c.duration){update(transitionVP(s,'finish',c.duration));return true;}return false;}
 load();
 document.body.insertAdjacentHTML('beforeend',`<dialog id="vp-start-dialog" aria-labelledby="vp-start-title"><div class="dialog-head"><div><span class="eyebrow">VIRTUAL PARTICIPATION</span><h2 id="vp-start-title">开始一场 VP</h2></div><button type="button" class="icon-btn" data-vp="close-start" aria-label="关闭 VP 设置">×</button></div><form id="vp-start-form"><div class="dialog-body"><p class="muted">与历史队伍在同一时间线上比赛。开赛后隐藏未来榜单，按真实经过时间推进。</p><div class="vp-fields"><div class="field"><label for="vp-contest">训练赛事</label><select id="vp-contest" name="contest" required></select></div><div class="field"><label for="vp-name">我的队名</label><input id="vp-name" name="name" value="我的 VP 队伍" maxlength="80" required></div><div class="field"><label for="vp-school">学校（可选）</label><input id="vp-school" name="school" maxlength="80" placeholder="我的学校"></div></div><div class="source-note">本工具不提供题面或代码评测。请在外部 OJ 做题，将 AC / WA 等判定手动记录到这里；记录时间取当前 VP 用时。VP 不计入正式队伍数量、题目公开阈值或正式奖牌名额。主动结束后可查看最终榜。</div><div id="vp-start-error" class="error" role="alert"></div></div><div class="dialog-footer"><span class="muted" style="font-size:10px">刷新仍继续计时 · 可主动暂停</span><button class="button primary" type="submit">开始计时 →</button></div></form></dialog>`);
 function startDialog(contestId=host.active().id){
  const existing=activeSession();if(existing){viewId=existing.id;save();host.select(existing.contestId);toast('已回到未结束的 VP，请先完成本场训练');return;}
  const eligible=host.contests().filter(c=>Array.isArray(c.submissions));
  if(!eligible.length){toast('请先导入含提交记录的赛事；最终快照无法用于 VP');return;}
  $('#vp-contest').innerHTML=eligible.map(c=>`<option value="${esc(c.id)}" ${c.id===contestId?'selected':''}>${esc(c.title)}</option>`).join('');
  $('#vp-start-error').textContent='';$('#vp-start-dialog').showModal();
 }
 function panel(c=host.active()){
  const s=selected(c);if(!s)return '';
  const ended=s.status==='finished',paused=s.status==='paused';
  return `<section class="vp-panel ${ended?'vp-finished':''}" aria-label="我的 VP 控制台"><div class="vp-panel-head"><div><span class="vp-tag">VP</span><strong>${esc(s.name)}</strong><span class="vp-status">${ended?'已结束':paused?'已暂停':'进行中'}</span></div><div class="vp-controls">${!ended?`<button class="button secondary small" data-vp="${paused?'resume':'pause'}">${icon(paused?'play':'pause')}${paused?'继续计时':'暂停'}</button><button class="button secondary small" data-vp="finish">结束 VP</button>`:`<button class="button secondary small" data-vp="exit">退出 VP 视图</button><button class="button primary small" data-vp="new">再来一场</button>`}</div></div><div class="vp-score-strip"><div><span>我的用时 / ${clock(c.duration)}</span><strong class="mono" id="vp-clock">${clock(elapsedMinutes(s,c.duration))}</strong></div><div><span>虚拟排位</span><strong id="vp-rank">—</strong></div><div><span>解题 / 罚时</span><strong id="vp-score">—</strong></div><div><span>${ended?'模拟奖牌':'当前预估奖牌'}</span><strong id="vp-medal">—</strong></div></div><p class="vp-explanation">${ended?'已结束训练，可复盘完整最终榜。VP 成绩单独插入，不占原比赛名次和名额。':paused?'计时已暂停。继续后才能记录判定；未来成绩、传统榜和最终榜仍保持隐藏。':'按真实时间推进；未公开题目对其他队伍隐藏，你始终能看到自己的记录。请在外部 OJ 做题后手动记录判定。'}</p>${!ended?`<form id="vp-result-form" class="vp-result-form"><label>题目<select name="problem" aria-label="VP 题目">${c.problems.map(p=>`<option value="${esc(p.id)}">${esc(p.id)}</option>`).join('')}</select></label><label>外部 OJ 判定<select name="verdict" aria-label="外部 OJ 判定"><option>AC</option><option>WA</option><option>TLE</option><option>RE</option><option>MLE</option><option>OLE</option><option>PE</option><option>CE</option></select></label><button type="submit" class="button primary small" ${paused?'disabled':''}>记录当前判定</button><button type="button" class="text-button" data-vp="undo" ${!s.submissions.length||paused?'disabled':''}>撤销上一条</button></form>`:''}<div class="vp-panel-foot"><span id="vp-last-record">${lastRecord(s)}</span><div><button class="text-button" data-vp="locate">定位我的队伍</button><button class="text-button" data-vp="export">导出 VP 记录 ↗</button></div></div></section>`;
 }
 function lastRecord(s){const last=s.submissions.at(-1);return last?`共 ${s.submissions.length} 条记录 · 最近：${esc(last.problemId)} / ${last.verdict} / ${clock(last.time)}`:'尚未记录判定。CE 不计罚时，未通过题不计总罚时。';}
 function syncPanel(state){const s=selected();if(!s||!$('#vp-clock'))return;const row=state.rows.find(r=>r.virtual);$('#vp-clock').textContent=clock(elapsedMinutes(s,host.active().duration));$('#vp-rank').textContent=row?`# ${row.virtualRank}`:'—';$('#vp-score').textContent=row?`${row.solved} / ${row.penalty}`:'—';$('#vp-medal').innerHTML=row?host.medalBadge(row):'—';}
 function page(){
  const all=host.contests();const existing=activeSession();
  return host.title('VIRTUAL PARTICIPATION','VP 训练','以自己的节奏，与历史赛场同台。',`<button class="button primary" data-vp="new">${icon('play')} 开始 VP</button>`)+`<section class="content-panel"><h2>选择赛事，开始模拟参赛</h2><p>实时计时推进历史榜单；可暂停、继续和保存进度。支持手动记录外部 OJ 的评测结果，不提供代码自动评测。只有含提交记录的赛事支持 VP。</p>${existing?`<div class="source-note">你有一场${existing.status==='paused'?'已暂停':'进行中'}的 VP：<strong>${esc(existing.name)}</strong>。<button class="text-button" data-vp-view="${esc(existing.id)}">回到比赛 →</button></div>`:''}</section><div class="vp-contest-grid">${all.map(c=>`<article class="content-panel"><div class="contest-mark">${icon('trophy')}</div><h2 style="margin-top:15px">${esc(c.title)}</h2><p>${c.teams.length} 支历史队伍 · ${c.problems.length} 道题目 · ${clock(c.duration)}</p><button class="button ${c.submissions?'primary':'secondary'} small" style="margin-top:15px" data-vp-contest="${esc(c.id)}" ${!c.submissions?'disabled':''}>${c.submissions?'开始本场 VP →':'最终快照 · 无法 VP'}</button></article>`).join('')}</div><section class="content-panel"><h2>我的 VP 记录 <span class="tag">${sessions.length}</span></h2>${sessions.length?sessions.slice().reverse().map(s=>{const c=all.find(x=>x.id===s.contestId);return `<div class="vp-history-row"><div><strong>${esc(s.name)}</strong><p>${esc(c.title)} · ${s.status==='finished'?'已结束':s.status==='paused'?'暂停中':'进行中'} · ${clock(elapsedMinutes(s,c.duration))} · ${s.submissions.length} 条记录</p></div><button class="button secondary small" data-vp-view="${esc(s.id)}">${s.status==='finished'?'查看复盘':'回到比赛'} →</button></div>`;}).join(''):'<p>还没有 VP 记录。开始一场训练后，进度会保存在当前浏览器。</p>'}</section>`;
 }
 $('#vp-start-form').addEventListener('submit',e=>{
  e.preventDefault();try{if(activeSession())throw Error('已有未结束的 VP');const form=e.target.elements,c=host.contests().find(c=>c.id===form.contest.value);const s={...createVP(c,form.name.value,form.school.value),rules:{...host.rules(c)},medals:{...host.medals(c)},medalPolicy:host.medalPolicy?.(c)||null};sessions.push(s);viewId=s.id;save();$('#vp-start-dialog').close();host.select(c.id);toast('VP 已开始，请使用外部 OJ 做题并在这里记录判定');}catch(error){$('#vp-start-error').textContent=error.message;}
 });
 document.addEventListener('submit',e=>{if(e.target.id!=='vp-result-form')return;e.preventDefault();try{const s=selected(),c=host.active();update(recordVP(s,c,e.target.elements.problem.value,e.target.elements.verdict.value));toast('已记录当前时间的评测结果');}catch(error){toast(error.message);finishIfExpired();}});
 document.addEventListener('click',e=>{
  const view=e.target.closest('[data-vp-view]');if(view){const s=sessions.find(s=>s.id===view.dataset.vpView);viewId=s.id;save();host.select(s.contestId);return;}
  const contest=e.target.closest('[data-vp-contest]');if(contest&&!contest.disabled){startDialog(contest.dataset.vpContest);return;}
  const el=e.target.closest('[data-vp]');if(!el||el.disabled)return;const action=el.dataset.vp,s=selected(),c=host.active();
  try{switch(action){case'new':startDialog();break;case'control':$('.vp-panel')?.scrollIntoView({block:'start',behavior:'smooth'});break;case'close-start':$('#vp-start-dialog').close();break;case'pause':case'resume':if(!finishIfExpired())update(transitionVP(s,action,c.duration));break;case'finish':update(transitionVP(s,'finish',c.duration));toast('VP 已结束，已开放最终榜单复盘');break;case'exit':if(locked())throw Error('请先结束 VP');viewId=null;save();host.change();break;case'undo':if(s.status!=='running')throw Error('请先继续 VP');update({...s,submissions:s.submissions.slice(0,-1)});toast('已撤销上一条判定');break;case'locate':host.locate();break;case'export':host.download(JSON.stringify({...s,contestTitle:c.title,note:'手动记录外部 OJ 判定的 VP 训练数据'},null,2),`${c.title}-${s.name}-VP.json`);break;}}catch(error){toast(error.message);}
 });
 window.addEventListener('storage',e=>{if(e.key===KEY){load();host.change();}});
 setInterval(()=>{if(finishIfExpired())return;if(selected()?.status==='running')host.tick();},1000);
 return {selected,locked,rules,medals,medalPolicy,panel,page,syncPanel,startDialog,activeSession,removeContest(id){sessions=sessions.filter(s=>s.contestId!==id);if(!sessions.some(s=>s.id===viewId))viewId=null;save();}};
}
